"""Tenant identity and permission records."""
from dataclasses import dataclass, field
from typing import Set, Dict, Any

@dataclass
class TenantContext:
    tenant_id: str
    tenant_name: str = ""
    allowed_scopes: Set[str] = field(default_factory=set)
    is_active: bool = True

    def permits(self, scope: str) -> bool:
        if not self.is_active:
            return False

        for allowed in self.allowed_scopes:
            if self._match_scope(allowed, scope):
                return True
        return False

    def _match_scope(self, pattern: str, scope: str) -> bool:
        pattern_parts = pattern.split('::')
        scope_parts = scope.split('::')
        return self._match_recursive(pattern_parts, 0, scope_parts, 0)

    def _match_recursive(self, pattern_parts: list, p_idx: int, scope_parts: list, s_idx: int) -> bool:
        if p_idx == len(pattern_parts):
            return s_idx == len(scope_parts)

        if pattern_parts[p_idx] == '**':
            # ** matches zero or more segments
            for k in range(s_idx, len(scope_parts) + 1):
                if self._match_recursive(pattern_parts, p_idx + 1, scope_parts, k):
                    return True
            return False

        if s_idx == len(scope_parts):
            return False

        if pattern_parts[p_idx] == '*' or pattern_parts[p_idx] == scope_parts[s_idx]:
            return self._match_recursive(pattern_parts, p_idx + 1, scope_parts, s_idx + 1)

        return False

    def add_scope(self, scope: str) -> None:
        self.allowed_scopes.add(scope)

    def to_dict(self) -> Dict[str, Any]:
        return {"tenant_id": self.tenant_id, "tenant_name": self.tenant_name, "is_active": self.is_active}
